// Normalize + validate the GuardX payload.
// Optional shared-secret check: set GUARDX_WEBHOOK_SECRET in the n8n
// environment (same value as GuardX N8N_WEBHOOK_SECRET). When empty,
// the check is skipped so the workflow works out of the box.
const expected = $env.GUARDX_WEBHOOK_SECRET || '';
const got = ($('GuardX Webhook').first().json.headers || {})['x-guardx-webhook-secret'] || '';
if (expected && got !== expected) {
  throw new Error('unauthorized webhook call: bad or missing secret');
}

const p = $('GuardX Webhook').first().json.body || $('GuardX Webhook').first().json;
const severity = String(p.severity || 'UNKNOWN').toUpperCase();
const status = p.status || 'unknown';
const urgent = ['HIGH', 'CRITICAL'].includes(severity);

return [{
  json: {
    source: p.source || 'guardx',
    event_id: p.event_id,
    event_type: p.event_type,
    occurred_at: p.occurred_at,
    camera_id: p.camera_id,
    zone_id: p.zone_id,
    zone_name: p.zone_name,
    source_event_type: p.source_event_type,
    track_id: p.track_id,
    detection_confidence: p.detection_confidence,
    incident_id: p.incident_id,
    workflow_id: p.workflow_id,
    status,
    severity,
    summary: p.summary,
    analysis: p.analysis,
    cited_policy_chunk_ids: p.cited_policy_chunk_ids || [],
    retrieved_policy_count: p.retrieved_policy_count,
    reprocessed: !!p.reprocessed,
    urgent,
    alert_level: urgent ? 'URGENT' : 'STANDARD',
    title: p.event_type === 'zone_event'
      ? `Zone ${p.source_event_type || 'event'}: ${p.zone_name || 'unknown zone'}`
      : `Incident [${status}]: ${p.zone_name || 'unknown zone'}`
  }
}];
